 TypedWakeTasks(LinearLayout card,String type,String run,int unit,int minimum,Bundle restored,java.util.function.BooleanSupplier current,Runnable complete,boolean practiceJournal){this.practiceJournal=practiceJournal;activity=(Activity)card.getContext();this.type=type;this.run=run;this.unit=unit;this.minimum=minimum;this.current=current;this.complete=complete;key=JournalRule.owner(run,unit);boolean journal=type.equals("Dream journal");if(journal&&practiceJournal)Design.text(card,"Practice only · this entry is not saved.",13,400,Design.MUTED);Design.text(card,journal?"Write your morning journal":"Read the mirrored phrase",22,600,Design.INK);Design.space(card,12);String phrase=MirrorText.phrase(run,unit);if(!journal){TextView mirrored=Design.text(card,phrase,25,600,Design.BROWN);mirrored.setGravity(Gravity.CENTER);mirrored.setScaleX(-1f);mirrored.setTextIsSelectable(false);mirrored.setContentDescription("Mirrored phrase: "+phrase);Design.space(card,16);}else{Design.text(card,"At least "+minimum+" letters or digits, 8 words and 5 different words. A dream or morning reflection is fine.",13,400,Design.MUTED);Design.space(card,12);}input=new EditText(activity);input.setContentDescription(journal?"Journal challenge entry":"Mirror phrase answer");input.setInputType(InputType.TYPE_CLASS_TEXT|(journal?InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES:InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS)|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);input.setTextSize(17*Appearance.scale(activity));input.setTypeface(Design.font(activity,400));input.setTextColor(Design.INK);input.setHint(journal?"What do you remember? How are you feeling?":"Type the phrase normally");input.setHintTextColor(Design.MUTED);input.setMinLines(journal?4:1);input.setMaxLines(journal?8:3);input.setBackground(Design.outline(activity,Design.SOFT,Design.LINE,16));Design.pad(input,14,14);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(journal?JournalRule.MAX:120)});if(restored!=null&&key.equals(restored.getString("key"))&&type.equals(restored.getString("type")))input.setText(restored.getString("text",""));card.addView(input,new LinearLayout.LayoutParams(-1,-2));feedback=Design.text(card,"",13,500,Design.BROWN);submit=Design.button(card,journal?practiceJournal?"Check practice entry":"Save entry & continue":"Check mirrored phrase",true,()->{if(closed||!current.getAsBoolean())return;if(!journal){if(MirrorText.accepts(phrase,input.getText().toString()))complete.run();else feedback.setText("Type the entire phrase normally, including its digits.");return;}String text=input.getText().toString();String problem=JournalRule.problem(text,minimum);if(!problem.isEmpty()){feedback.setText(problem);return;}if(practiceJournal){complete.run();return;}try{write=JournalWrites.start(activity,key,text,minimum,current);poll();}catch(RuntimeException failure){feedback.setText(failure.getMessage());}});if(journal&&!practiceJournal&&restored!=null&&key.equals(restored.getString("key"))&&restored.getBoolean("writing")){write=JournalWrites.start(activity,key,input.getText().toString(),minimum,current);main.post(this::poll);}}
 void poll(){if(closed)return;if(write==null)return;input.setEnabled(false);submit.setEnabled(false);if(!write.done){feedback.setText("Saving private journal…");main.postDelayed(this::poll,100);return;}JournalWrites.Operation done=write;write=null;JournalWrites.forget(key);if(!current.getAsBoolean())return;if(done.error.isEmpty()){complete.run();return;}input.setEnabled(true);submit.setEnabled(true);feedback.setText(done.error);}
 Bundle state(){Bundle b=new Bundle();b.putString("key",key);b.putString("type",type);b.putString("text",input.getText().toString());b.putBoolean("writing",write!=null);return b;}
